// CONFIGURACIÓN MAXIMA CONVERSIÓN
const config = {
  servicios: [
    { id: 1, nombre: "Gestión Email", precio: 25, descripcion: "Organización bandeja entrada, filtros, respuestas automáticas" },
    { id: 2, nombre: "Calendarización", precio: 25, descripcion: "Gestión citas, coordinación horarios, recordatorios" },
    { id: 3, nombre: "Tareas Repetitivas", precio: 25, descripcion: "Automatización procesos manuales, formateo documentos" },
    { id: 4, nombre: "Redes Sociales", precio: 28, descripcion: "Calendarización contenido, creación posts, engagement" },
    { id: 5, nombre: "Email Marketing", precio: 28, descripcion: "Newsletters, secuencias automatizadas, segmentación" },
    { id: 6, nombre: "Gestión CRM", precio: 26, descripcion: "Seguimiento leads, actualización contactos, reportes" },
    { id: 8, nombre: "Investigación", precio: 27, descripcion: "Market research, análisis competencia, recopilación datos" },
    { id: 9, nombre: "Soporte Clientes", precio: 25, descripcion: "Respuesta consultas, gestión tickets, onboarding" },
    { id: 11, nombre: "Gestión Contenido", precio: 28, descripcion: "Research blogs, formateo contenidos, SEO básico" },
    { id: 12, nombre: "Automatización", precio: 32, descripcion: "Setup Zapier/n8n, integración apps, workflows" },
    { id: 13, nombre: "Gestión Financiera", precio: 26, descripcion: "Seguimiento gastos, facturas, recordatorios pagos" },
    { id: 14, nombre: "Soporte Ejecutivo", precio: 30, descripcion: "Presentaciones, gestión viajes, coordinación eventos" },
    { id: 15, nombre: "Gestión Comunidades", precio: 27, descripcion: "Moderación, engagement, programación eventos" }
  ],
  paquetes: {
    basico: { 
      precio: 390, 
      horas: 15, 
      servicios: [1, 2, 3, 8],
      descripcion: "Ideal para autónomos que necesitan recuperar tiempo" 
    },
    profesional: { 
      precio: 650, 
      horas: 25, 
      servicios: [1, 2, 4, 6, 3, 8],
      descripcion: "Perfecto para PYMEs que quieren escalar marketing" 
    },
    premium: { 
      precio: 980, 
      horas: 35, 
      servicios: [1, 2, 4, 5, 6, 12, 3, 11],
      descripcion: "Para negocios en crecimiento acelerado" 
    }
  },
  telegram_bot: "@manuelasanchez_n8n_bot",
  objetivo_diario: "5 prospectos contactados",
  tasa_conversion_esperada: "15-20%"
};

return [{ json: config }];

// ANALIZAR Y FILTRAR PROSPECTOS DE ALTA CALIDAD
const items = $input.all();
const configNode = $('ConfiguracionServicios').first();
const config = configNode ? configNode.json : {};

const prospectsFiltrados = items.map(item => {
  const data = item.json;

  // Extraer campos del scraping de LinkedIn
  const nombre = data.name || data.firstName || '';
  const apellido = data.lastName || '';
  const cargo = data.headline || data.title || 'Profesional';
  const empresa = data.company || 'Autónomo/Freelance';
  const linkedinUrl = data.url || data.publicIdentifier || '';

  // Detectar necesidades específicas basado en perfil
  let necesidades = [];
  let urgencia = 5;
  const perfil = (cargo + ' ' + empresa).toLowerCase();

  // Asignar necesidades según tipo de perfil
  if (perfil.includes('diseñador') || perfil.includes('designer') || perfil.includes('creativo')) {
    necesidades = [4, 5, 11, 15]; // Marketing y contenido
    urgencia = 7;
  } else if (perfil.includes('programador') || perfil.includes('developer') || perfil.includes('tech')) {
    necesidades = [1, 2, 12, 8]; // Automatización y organización
    urgencia = 6;
  } else if (perfil.includes('consultor') || perfil.includes('consultant') || perfil.includes('asesor')) {
    necesidades = [1, 2, 6, 9, 14]; // CRM y soporte ejecutivo
    urgencia = 8;
  } else if (perfil.includes('coach') || perfil.includes('mentor') || perfil.includes('formador')) {
    necesidades = [4, 5, 6, 15, 9]; // Marketing y comunidades
    urgencia = 7;
  } else if (perfil.includes('director') || perfil.includes('gerente') || perfil.includes('manager')) {
    necesidades = [1, 2, 6, 14, 8]; // Gestión ejecutiva
    urgencia = 9;
  } else {
    necesidades = [1, 2, 3, 4]; // Servicios básicos
    urgencia = 6;
  }

  // Determinar paquete recomendado
  let paquete = 'basico';
  if (necesidades.length >= 6) paquete = 'premium';
  else if (necesidades.length >= 4) paquete = 'profesional';

  // Calcular valor potencial mensual
  const valorPotencial = config.paquetes && config.paquetes[paquete] ? config.paquetes[paquete].precio : 390;

  return {
    json: {
      nombre: nombre,
      apellido: apellido,
      cargo: cargo,
      empresa: empresa,
      linkedinUrl: linkedinUrl,
      necesidades_detectadas: necesidades,
      paquete_recomendado: paquete,
      urgencia_score: urgencia,
      valor_potencial_mensual: valorPotencial,
      probabilidad_conversion: Math.min(90, urgencia * 10 + 20),
      estado: 'prospecto_calificado',
      fecha_captacion: new Date().toISOString()
    }
  };
}).filter(prospect => prospect.json.urgencia_score >= 6); // Solo prospects con urgencia alta

console.log(`🔥 Prospects calificados: ${prospectsFiltrados.length}`);
return prospectsFiltrados;

// PREPARAR EJECUCIÓN FINAL CON MÁXIMO VALOR
const prospecto = $json;

// Obtener outputs de los agentes
const copywriterNode = $('AgentCopywriter').first();
const estrategiaNode = $('AgentEstrategia').first();
const seguimientoNode = $('AgentSeguimiento').first();

const mensajeInicial = copywriterNode ? (copywriterNode.json.output || copywriterNode.json.text || copywriterNode.json) : 'Mensaje pendiente de generar';
const estrategia = estrategiaNode ? (estrategiaNode.json.output || estrategiaNode.json) : {};
const seguimientos = seguimientoNode ? (seguimientoNode.json.output || seguimientoNode.json) : {};

// Parsear seguimientos si viene como string JSON
let seguimientosParsed = seguimientos;
if (typeof seguimientos === 'string') {
  try {
    seguimientosParsed = JSON.parse(seguimientos);
  } catch (e) {
    seguimientosParsed = { seguimiento_1: seguimientos, seguimiento_2: '' };
  }
}

const ejecucionFinal = {
  estado: "LISTO_PARA_EJECUTAR",
  prospecto: {
    nombre: prospecto.nombre,
    apellido: prospecto.apellido,
    cargo: prospecto.cargo,
    empresa: prospecto.empresa,
    linkedin: prospecto.linkedinUrl,
    necesidades: prospecto.necesidades_detectadas,
    paquete: prospecto.paquete_recomendado,
    valor_mensual: prospecto.valor_potencial_mensual,
    urgencia: prospecto.urgencia_score,
    probabilidad: prospecto.probabilidad_conversion
  },
  mensajeria: {
    mensaje_inicial: mensajeInicial,
    seguimiento_48h: seguimientosParsed.seguimiento_1 || '',
    seguimiento_5dias: seguimientosParsed.seguimiento_2 || '',
    bot_telegram: "@manuelasanchez_n8n_bot",
    instrucciones: "El prospecto escribe 'Hola' al bot y menciona 'Asistente Virtual'"
  },
  estrategia_venta: estrategia,
  metricas: {
    valor_potencial_12_meses: prospecto.valor_potencial_mensual * 12,
    expected_conversion: prospecto.probabilidad_conversion + "%",
    tiempo_estimado_cierre: prospecto.urgencia_score >= 8 ? "3-7 días" : "7-14 días",
    prioridad: prospecto.urgencia_score >= 8 ? "ALTA" : "MEDIA"
  },
  timestamp: new Date().toISOString(),
  campaign_id: `av_${prospecto.nombre.toLowerCase().replace(/\s/g, '_')}_${Date.now()}`
};

return [{ json: ejecucionFinal }];

// GENERAR RESUMEN EJECUTIVO PARA TELEGRAM
const items = $input.all();

const resumen = {
  total_prospectos: items.length,
  prospectos_alta_prioridad: items.filter(p => p.json.metricas.prioridad === 'ALTA').length,
  valor_potencial_total: items.reduce((sum, p) => sum + p.json.prospecto.valor_mensual, 0),
  valor_potencial_anual: items.reduce((sum, p) => sum + (p.json.prospecto.valor_mensual * 12), 0),

  top_prospectos: items
    .sort((a, b) => b.json.prospecto.urgencia - a.json.prospecto.urgencia)
    .slice(0, 5)
    .map(p => ({
      nombre: `${p.json.prospecto.nombre} ${p.json.prospecto.apellido}`,
      empresa: p.json.prospecto.empresa,
      paquete: p.json.prospecto.paquete,
      valor_mensual: p.json.prospecto.valor_mensual,
      urgencia: p.json.prospecto.urgencia
    }))
};

const mensajeTelegram = `🎯 *NUEVOS PROSPECTOS ASISTENTE VIRTUAL*\n\n📊 *Resumen Ejecutivo:*\n✅ Total prospects: ${resumen.total_prospectos}\n🔥 Alta prioridad: ${resumen.prospectos_alta_prioridad}\n💰 Valor potencial/mes: €${resumen.valor_potencial_total}\n📈 Valor potencial/año: €${resumen.valor_potencial_anual}\n\n🏆 *TOP 5 PROSPECTOS:*\n${resumen.top_prospectos.map((p, i) => 
  `${i + 1}. *${p.nombre}* | ${p.empresa}\n   📦 ${p.paquete.toUpperCase()} | 💰 €${p.valor_mensual}/mes | 🚨 ${p.urgencia}/10`
).join('\n\n')}\n\n🤖 *BOT ACTIVO:* @manuelasanchez_n8n_bot\n💬 *Instrucciones:* Prospectos escriben 'Hola' y mencionan 'Asistente Virtual'\n\n⚡ *¡A por esos clientes!*`;

return [{ json: { resumen, mensajeTelegram } }];
